  'phonetics.subtype_label_batchim': "Batchim (final consonant)",
  'phonetics.rules_intro_title': "Why is Korean **written** differently from how it's **read**?",
  'phonetics.rules_intro_body': "Korean letters were created by **King Sejong** in 1443 based on the shape of speech organs — each letter has an “original” sound. But when letters form words, neighboring sounds affect each other: **aspiration, nasalization, and tongue position** naturally shift toward the easiest path, so spelling and pronunciation diverge.",
  'phonetics.rules_intro_divider': "Here are the 10 major sound change rules",
  'phonetics.rules_intro_outro': "Not rigid rules, but “economy patterns” — listen to each one twice with real recordings, and your tongue will remember naturally.",
  'phonetics.order_eyebrow': "◆ Application order · 음운 규칙의 적용 순서",
  'phonetics.order_title': "When a letter undergoes multiple sound changes, which comes first?",
  'phonetics.order_body': "When confused about a word's pronunciation, follow this order: **First determine the final consonant's base sound → see what follows → decide between linking or neutralization → then check if tensification/nasalization/aspiration applies**.",
  'phonetics.order_s1_label': "Neutralization",
  'phonetics.order_s1_desc': "If this letter is pronounced alone (or followed by a consonant), change ㅅ/ㅆ/ㅈ/ㅊ/ㅌ/ㅎ to ㄷ; ㅋ/ㄲ to ㄱ; ㅍ to ㅂ. This is the starting point for all sound changes.",
  'phonetics.order_s2_label': "Linking Check",
  'phonetics.order_s2_desc': "Check the next syllable: starts with a vowel and is a particle/ending → use original sound linking; starts with a vowel but is an independent word → use representative sound linking (절음법칙).",
  'phonetics.order_s3_label': "Combined Changes",
  'phonetics.order_s3_desc': "If not linked, look at the two consonants: ㄱ/ㄷ/ㅂ become tense, before ㄴ/ㅁ become nasal, before ㅎ become aspirated, ㄴㄹ become liquid.",
  'phonetics.order_s4_label': "Deletion / Addition",
  'phonetics.order_s4_desc': "ㅎ is dropped before a vowel; some compound words add ㄴ in the middle. These 'invisible changes' are checked last.",
  'phonetics.rule_formula_word': "Formula",
  'phonetics.rule_lettergroups_title': "↳ Letters treated the same in this rule",
  'phonetics.rule_examples_title': "Real Examples",
  'phonetics.rule_examples_hint': "Tap **Write** to hear the unchanged reading, tap **Read** to hear the actual changed pronunciation",
  'phonetics.rule_sentences_title': "In Sentences",
  'phonetics.rule_sentences_hint': "Highlighted parts undergo sound change · Tap **Read** to hear the actual flow",
  'phonetics.rule_pitfalls_title': "⚠ Common Mistakes for Chinese Learners",
  'phonetics.rule_num': "Rule {n}",
